<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Domain;

use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetUidVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetCodeVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor\SnippetCodeAccessor;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetTenantVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor\SnippetTenantAccessor;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetEnabledVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor\SnippetEnabledAccessor;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetVersionVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor\SnippetVersionAccessor;
use Civi\Lughauth\Features\Document\Snippet\Domain\Formula\EnabledCalculator;
use Civi\Lughauth\Features\Document\Snippet\Domain\Event\SnippetCreateEvent;
use Civi\Lughauth\Features\Document\Snippet\Domain\Event\SnippetUpdateEvent;
use Civi\Lughauth\Features\Document\Snippet\Domain\Event\SnippetDeleteEvent;
use Civi\Lughauth\Features\Document\Snippet\Domain\Event\SnippetEnableEvent;
use Civi\Lughauth\Features\Document\Snippet\Domain\Event\SnippetDisableEvent;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

class Snippet extends SnippetRef
{
    use SnippetCodeAccessor;
    use SnippetTenantAccessor;
    use SnippetEnabledAccessor;
    use SnippetVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        SnippetUidVO|string $uid,
        SnippetCodeVO|string $code,
        SnippetTenantVO|TenantRef|null $tenant = null,
        SnippetEnabledVO|bool|null $enabled = null,
        SnippetVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_code = SnippetCodeVO::from($code);
        $this->_tenant = null === $tenant ? SnippetTenantVO::empty() : SnippetTenantVO::from($tenant);
        $this->_enabled = null === $enabled ? SnippetEnabledVO::empty() : SnippetEnabledVO::from($enabled);
        $this->_version = null === $version ? SnippetVersionVO::empty() : SnippetVersionVO::from($version);
    }
    public function replace(SnippetAttributes $values): Snippet
    {
        $value = clone $this;
        $value->_code = $values->getCodeOrCurrent($this->_code);
        $value->_tenant = $values->getTenantOrCurrent($this->_tenant);
        $value->_enabled = $values->getEnabledOrCurrent($this->_enabled);
        $value->_version = $values->getVersionOrCurrent($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'enabled'];
    }
    public static function create(SnippetAttributes $values): Snippet
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled());
        $value = $calculated->createNewInstance();
        $value->recordedEvents[] = new SnippetCreateEvent($value);
        return $value;
    }
    public function update(SnippetAttributes $values): Snippet
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new SnippetUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): Snippet
    {
        $value = clone $this;
        $value->recordedEvents[] = new SnippetDeleteEvent($value);
        return $value;
    }
    public function enable(): Snippet
    {
        $value = clone $this;
        $value->_enabled = SnippetEnabledVO::from(true);
        $value->recordedEvents[] = new SnippetEnableEvent($value, original: $this);
        return $value;
    }
    public function disable(): Snippet
    {
        $value = clone $this;
        $value->_enabled = SnippetEnabledVO::from(false);
        $value->recordedEvents[] = new SnippetDisableEvent($value, original: $this);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['code'] = $this->getCode();
        $tenant = $this->getTenant();
        if (null !== $tenant) {
            $data['tenant'] = ['$ref' => $tenant->uid() ];
        }
        $data['enabled'] = $this->isEnabled();
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): SnippetAttributes
    {
        return (new SnippetAttributes())
          ->uid($this->uid())
          ->code($this->_code)
          ->tenant($this->_tenant)
          ->enabled($this->_enabled)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
